use std::path::Path;

use anyhow::Result;
use unicodex_core::ObjectStore;

use super::CapsuleClosure;
use crate::object_peer::chunked::auth::ChunkedAuth;
use crate::object_peer::chunked::AuthenticatedTranscript;
use crate::OutputFormat;

mod output;
mod replay;
mod value;

pub(in crate::program_module::runtime) const SCHEMA: &str =
    "unicodex.foreign_process.authenticated_peer_provision_receipt.v1";
pub(in crate::program_module::runtime) const PROFILE: &str =
    "exact_pairwise_authenticated_chunked_transcript_replay.v1";
const KIND: &str = "foreign_process_authenticated_peer_provision_receipt";

pub(in crate::program_module::runtime::foreign_process) struct Composition {
    pub(in crate::program_module::runtime::foreign_process) module_cid: String,
    pub(in crate::program_module::runtime::foreign_process) capsule_root_cid: String,
    pub(in crate::program_module::runtime::foreign_process) closure_cid: String,
    pub(in crate::program_module::runtime::foreign_process) requester_node: String,
    pub(in crate::program_module::runtime::foreign_process) source_node: String,
    pub(in crate::program_module::runtime::foreign_process) auth_key_id: String,
    pub(in crate::program_module::runtime::foreign_process) runtime_protocol_descriptor: String,
    pub(in crate::program_module::runtime::foreign_process) network_requests: usize,
}

pub(super) struct Construction<'a> {
    pub(super) closure: &'a CapsuleClosure,
    pub(super) requester_node: &'a str,
    pub(super) source_node: &'a str,
    pub(super) auth: &'a ChunkedAuth,
    pub(super) transcript: &'a AuthenticatedTranscript,
    pub(super) manifest_cid: &'a str,
    pub(super) objects: usize,
    pub(super) object_bytes: usize,
    pub(super) chunk_count: usize,
    pub(super) network_requests: usize,
}

pub(super) fn store(store: &ObjectStore, construction: Construction<'_>) -> Result<String> {
    value::store(store, construction)
}

pub(super) fn verify_command(
    store: &ObjectStore,
    receipt_cid: &str,
    auth_key: &Path,
    format: OutputFormat,
) -> Result<i32> {
    let result =
        ChunkedAuth::load(auth_key).and_then(|auth| replay::verify(store, receipt_cid, &auth));
    let (output, code) = match result {
        Ok(verified) => (output::accepted(receipt_cid, verified), 0),
        Err(_) => (output::rejected(receipt_cid), 2),
    };
    output::emit(&output, format)?;
    Ok(code)
}

pub(in crate::program_module::runtime::foreign_process) fn verify_for_composition(
    store: &ObjectStore,
    receipt_cid: &str,
    auth: &ChunkedAuth,
) -> Result<Composition> {
    let verified = replay::verify(store, receipt_cid, auth)?;
    Ok(Composition {
        module_cid: verified.receipt.module,
        capsule_root_cid: verified.closure.capsule_cid,
        closure_cid: verified.closure.closure_cid,
        requester_node: verified.receipt.requester_node,
        source_node: verified.receipt.source_node,
        auth_key_id: verified.receipt.auth_key_id,
        runtime_protocol_descriptor: verified.receipt.runtime_protocol_descriptor,
        network_requests: verified.receipt.network_requests,
    })
}

