mod tests {
    use std::sync::{Arc, Barrier};

    use unicodex_core::cid_for_bytes;

    use super::*;

    #[test]
    fn one_concurrent_distributed_consumer_wins() {
        let work = tempfile::tempdir().unwrap();
        let cid = cid_for_bytes(b"distributed benchmark authorization concurrency fixture");
        issue(&ObjectStore::open(work.path()), &cid).unwrap();
        let barrier = Arc::new(Barrier::new(8));
        let workers = (0..8)
            .map(|_| {
                let root = work.path().to_owned();
                let cid = cid.clone();
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    barrier.wait();
                    consume(&ObjectStore::open(root), &cid).is_ok()
                })
            })
            .collect::<Vec<_>>();
        assert_eq!(
            workers
                .into_iter()
                .map(|worker| usize::from(worker.join().unwrap()))
                .sum::<usize>(),
            1
        );
    }
}

